  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ---------------- Enums ----------------\n\nenum Role {\n  CUSTOMER\n  DRIVER\n  PROVIDER\n  ADMIN\n}\n\nenum OrderStatus {\n  PENDING\n  ACCEPTED\n  PREPARING\n  READY_FOR_PICKUP\n  OUT_FOR_DELIVERY\n  DELIVERED\n  REJECTED\n  CANCELLED\n}\n\nenum RequestStatus {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\n// ---------------- User & Role Profiles ----------------\n\nmodel User {\n  id        String  @id @default(cuid())\n  clerkId   String  @unique\n  email     String  @unique\n  name      String\n  phone     String?\n  avatarUrl String? // link to image, not a stored file\n  role      Role    @default(CUSTOMER)\n\n  customerProfile CustomerProfile?\n  providerProfile ProviderProfile?\n  driverProfile   DriverProfile?\n\n  restaurants    Restaurant[] // as owner\n  addresses      Address[]\n  cart           Cart?\n  customerOrders Order[]        @relation(\"CustomerOrders\")\n  driverOrders   Order[]        @relation(\"DriverOrders\")\n  favorites      Favorite[]\n  reviews        Review[]\n  notifications  Notification[]\n  roleRequests   RoleRequest[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([clerkId])\n  @@index([role])\n}\n\nmodel CustomerProfile {\n  id            String @id @default(cuid())\n  userId        String @unique\n  user          User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  loyaltyPoints Int    @default(0)\n  totalOrders   Int    @default(0)\n  totalSpent    Float  @default(0)\n}\n\nmodel ProviderProfile {\n  id            String  @id @default(cuid())\n  userId        String  @unique\n  user          User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  businessName  String\n  businessPhone String?\n  verified      Boolean @default(false)\n}\n\nmodel DriverProfile {\n  id               String  @id @default(cuid())\n  userId           String  @unique\n  user             User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  vehicleType      String\n  plateNumber      String\n  licenseNumber    String?\n  isOnline         Boolean @default(false)\n  currentLatitude  Float?\n  currentLongitude Float?\n}\n\n// ---------------- Restaurant & Menu ----------------\n\nmodel Restaurant {\n  id            String  @id @default(cuid())\n  ownerId       String\n  owner         User    @relation(fields: [ownerId], references: [id])\n  name          String\n  description   String?\n  imageUrl      String? // link to image, not a stored file\n  coverImageUrl String? // link to image, not a stored file\n  address       String\n  phone         String?\n  email         String?\n  isOpen        Boolean @default(true)\n  rating        Float   @default(0)\n\n  menuItems MenuItem[]\n  orders    Order[]\n  reviews   Review[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel MenuItem {\n  id              String     @id @default(cuid())\n  restaurantId    String\n  restaurant      Restaurant @relation(fields: [restaurantId], references: [id], onDelete: Cascade)\n  name            String\n  description     String\n  image           String? // link to image, not a stored file\n  price           Float\n  category        String?\n  ingredients     String[]   @default([])\n  isPopular       Boolean    @default(false)\n  preparationTime Int? // minutes\n  available       Boolean    @default(true)\n\n  cartItems  CartItem[]\n  orderItems OrderItem[]\n  favorites  Favorite[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ---------------- Cart ----------------\n\nmodel Cart {\n  id     String     @id @default(cuid())\n  userId String     @unique\n  user   User       @relation(fields: [userId], references: [id], onDelete: Cascade)\n  items  CartItem[]\n}\n\nmodel CartItem {\n  id         String   @id @default(cuid())\n  cartId     String\n  cart       Cart     @relation(fields: [cartId], references: [id], onDelete: Cascade)\n  menuItemId String\n  menuItem   MenuItem @relation(fields: [menuItemId], references: [id])\n  quantity   Int      @default(1)\n\n  @@unique([cartId, menuItemId])\n}\n\n// ---------------- Address ----------------\n\nmodel Address {\n  id      String  @id @default(cuid())\n  userId  String\n  user    User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  label   String\n  address String\n  city    String\n  orders  Order[]\n}\n\n// ---------------- Orders ----------------\n\nmodel Order {\n  id           String      @id @default(cuid())\n  customerId   String\n  customer     User        @relation(\"CustomerOrders\", fields: [customerId], references: [id])\n  restaurantId String\n  restaurant   Restaurant  @relation(fields: [restaurantId], references: [id])\n  driverId     String?\n  driver       User?       @relation(\"DriverOrders\", fields: [driverId], references: [id])\n  addressId    String\n  address      Address     @relation(fields: [addressId], references: [id])\n  items        OrderItem[]\n  total        Float\n  status       OrderStatus @default(PENDING)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([status])\n  @@index([restaurantId])\n  @@index([customerId])\n}\n\nmodel OrderItem {\n  id           String   @id @default(cuid())\n  orderId      String\n  order        Order    @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  menuItemId   String\n  menuItem     MenuItem @relation(fields: [menuItemId], references: [id])\n  quantity     Int\n  priceAtOrder Float // snapshot of price at time of order, in case menu price changes later\n}\n\n// ---------------- Favorites, Reviews, Notifications ----------------\n\nmodel Favorite {\n  id         String   @id @default(cuid())\n  userId     String\n  menuItemId String\n  user       User     @relation(fields: [userId], references: [id])\n  menuItem   MenuItem @relation(fields: [menuItemId], references: [id])\n  createdAt  DateTime @default(now())\n\n  @@unique([userId, menuItemId])\n}\n\nmodel Review {\n  id           String     @id @default(cuid())\n  userId       String\n  restaurantId String\n  rating       Int\n  comment      String?\n  user         User       @relation(fields: [userId], references: [id])\n  restaurant   Restaurant @relation(fields: [restaurantId], references: [id])\n  createdAt    DateTime   @default(now())\n}\n\nmodel Notification {\n  id        String   @id @default(cuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id])\n  title     String\n  message   String\n  isRead    Boolean  @default(false)\n  createdAt DateTime @default(now())\n}\n\n// ---------------- Role Requests ----------------\n\nmodel RoleRequest {\n  id            String        @id @default(cuid())\n  userId        String\n  user          User          @relation(fields: [userId], references: [id])\n  requestedRole Role\n  status        RequestStatus @default(PENDING)\n  extraData     Json // vehicle info for DRIVER, restaurant info for PROVIDER\n  createdAt     DateTime      @default(now())\n}\n",
